import itertools

# Function to calculate n
def calculate_n(a, b, c):
    # Ensure distinct positive integers
    if a == b or b == c or a == c or a <= 0 or b <= 0 or c <= 0:
        return None

    S1 = a + b + c
    S2 = a*b + b*c + c*a

    numerator = S1 * (S2 + 1)
    denominator = 4 * a * b * c

    if denominator == 0:
        return None # Should not happen with positive integers

    # Check if n is an integer
    if numerator % denominator == 0:
        return numerator // denominator
    else:
        return None

# Iterate through all combinations of 3 distinct integers from {1, 2, 3, 4, 5}
values = [1, 2, 3, 4, 5]
results = {}

for combo in itertools.combinations(values, 3):
    a, b, c = combo
    n_val = calculate_n(a, b, c)

    if n_val is not None:
        # Store the result keyed by n_val
        if n_val not in results:
            results[n_val] = []
        results[n_val].append(combo)

print(f"Calculated results: {results}")
